[{"order":1,"type":"heading","text":"Unit Testing with PHPUnit"},{"order":2,"type":"paragraph","text":"Unit testing is a crucial part of software development, ensuring that individual units of code work as expected. PHPUnit is a popular and powerful testing framework for PHP."},{"order":3,"type":"subheading","text":"Installation"},{"order":4,"type":"paragraph","text":"The recommended way to install PHPUnit is using Composer, the dependency manager for PHP."},{"order":5,"type":"code","text":"composer require --dev phpunit/phpunit"},{"order":6,"type":"paragraph","text":"This command installs PHPUnit as a development dependency. After installation, you can typically find the PHPUnit executable in the 'vendor/bin' directory."},{"order":7,"type":"subheading","text":"Creating Your First Test"},{"order":8,"type":"paragraph","text":"Let's create a simple class and a corresponding test case."},{"order":9,"type":"code","text":"// src/Calculator.php
class Calculator {
    public function add(int $a, int $b): int {
        return $a + $b;
    }
}"},{"order":10,"type":"paragraph","text":"Now, create a test case for the 'Calculator' class. By convention, test classes are placed in a 'tests' directory and named with a 'Test' suffix."},{"order":11,"type":"code","text":"// tests/CalculatorTest.php
use PHPUnit\Framework\TestCase;

class CalculatorTest extends TestCase {
    public function testAdd(): void {
        $calculator = new Calculator();
        $result = $calculator->add(2, 3);
        $this->assertEquals(5, $result);
    }
}"},{"order":12,"type":"bullet_point","text":"The test class extends 'PHPUnit\Framework\TestCase'."},{"order":13,"type":"bullet_point","text":"Test methods start with 'test' (e.g., 'testAdd')."},{"order":14,"type":"bullet_point","text":"The '$this->assertEquals()' method is an assertion that checks if two values are equal."},{"order":15,"type":"subheading","text":"Running Tests"},{"order":16,"type":"paragraph","text":"To run the tests, navigate to the project's root directory in your terminal and execute the PHPUnit command."},{"order":17,"type":"code","text":"./vendor/bin/phpunit tests"},{"order":18,"type":"paragraph","text":"This command tells PHPUnit to run all test files in the 'tests' directory. PHPUnit will output the results of the tests, indicating whether they passed or failed."},{"order":19,"type":"subheading","text":"Assertions"},{"order":20,"type":"paragraph","text":"PHPUnit provides a wide range of assertions to verify different conditions. Here are some common ones:"},{"order":21,"type":"bullet_point","text":"'$this->assertEquals($expected, $actual)': Checks if two values are equal."},{"order":22,"type":"bullet_point","text":"'$this->assertSame($expected, $actual)': Checks if two values are identical (same type and value)."},{"order":23,"type":"bullet_point","text":"'$this->assertTrue($condition)': Checks if a condition is true."},{"order":24,"type":"bullet_point","text":"'$this->assertFalse($condition)': Checks if a condition is false."},{"order":25,"type":"bullet_point","text":"'$this->assertNull($value)': Checks if a value is null."},{"order":26,"type":"bullet_point","text":"'$this->assertNotNull($value)': Checks if a value is not null."},{"order":27,"type":"bullet_point","text":"'$this->assertGreaterThan($expected, $actual)': Checks if a value is greater than another."},{"order":28,"type":"subheading","text":"Test Doubles (Mocks, Stubs)"},{"order":29,"type":"paragraph","text":"When testing code that depends on external services or complex objects, it's often useful to use test doubles. PHPUnit provides features for creating mocks and stubs."},{"order":30,"type":"code","text":"// Example of using a mock object
use PHPUnit\Framework\TestCase;

class ExampleTest extends TestCase {
    public function testSomething(): void {
        $mock = $this->createMock(SomeClass::class);

        $mock->expects($this->once())
             ->method('doSomething')
             ->willReturn('mocked value');

        // Use the mock object in your test
    }
}"},{"order":31,"type":"subheading","text":"Configuration (phpunit.xml)"},{"order":32,"type":"paragraph","text":"PHPUnit can be configured using a 'phpunit.xml' file in the project's root directory. This file allows you to specify test directories, include paths, and other settings."},{"order":33,"type":"code","text":"<!-- phpunit.xml -->
<phpunit bootstrap="vendor/autoload.php">
    <testsuites>
        <testsuite name="My Project Test Suite">
            <directory>tests</directory>
        </testsuite>
    </testsuites>
</phpunit>"},{"order":34,"type":"subheading","text":"Conclusion"},{"order":35,"type":"paragraph","text":"PHPUnit is a powerful tool for writing and running unit tests in PHP. By writing comprehensive unit tests, you can improve the quality, reliability, and maintainability of your code."}]
